// presentation layer: only handles HTTP details
class OrderController {
  constructor(orderService) {
    this.orderService = orderService;
  }

  async placeOrder(req, res) {
    const order = await this.orderService.placeOrder(req.body);
    res.status(201).json(order);
  }
}

// business layer: holds the actual rules
class OrderService {
  constructor(orderRepository) {
    this.orderRepository = orderRepository;
  }

  async placeOrder(request) {
    if (request.quantity <= 0) {
      throw new Error("quantity must be positive");
    }
    const order = {
      userId: request.userId,
      itemId: request.itemId,
      quantity: request.quantity,
    };
    return this.orderRepository.save(order);
  }
}

// data layer: only knows how to read and write orders
class OrderRepository {
  constructor(db) {
    this.db = db;
  }

  async save(order) {
    const row = await this.db.query(
      "INSERT INTO orders (user_id, item_id, quantity) VALUES ($1, $2, $3) RETURNING *",
      [order.userId, order.itemId, order.quantity]
    );
    return row;
  }
}

